from collections import OrderedDict
class TTLCache:
    def __init__(self, capacity, clock):
        if capacity < 0:
            raise ValueError('negative capacity')
        self.capacity, self.clock = capacity, clock
        self.data = OrderedDict()
    def _purge(self):
        now = self.clock()
        for key, (_, deadline) in list(self.data.items()):
            if deadline is not None and now >= deadline:
                del self.data[key]
    def set(self, key, value, ttl=None):
        self._purge()
        if ttl is not None and ttl <= 0:
            self.data.pop(key, None)
            return
        if not self.capacity:
            return
        self.data[key] = (value, None if ttl is None else self.clock() + ttl)
        self.data.move_to_end(key)
        while len(self.data) > self.capacity:
            self.data.popitem(last=False)
    def get(self, key, default=None):
        self._purge()
        if key not in self.data:
            return default
        self.data.move_to_end(key)
        return self.data[key][0]
    def __len__(self):
        self._purge()
        return len(self.data)

from collections import defaultdict

def waves(graph):
    dependencies = {name: set(deps) for name, deps in graph.items()}
    nodes = set(dependencies)
    for deps in dependencies.values():
        nodes.update(deps)
    degree = {name: len(dependencies.get(name, ())) for name in nodes}
    children = defaultdict(set)
    for name, deps in dependencies.items():
        for dep in deps:
            children[dep].add(name)
    ready = sorted(name for name in nodes if degree[name] == 0)
    layers = []; completed = 0
    while ready:
        layers.append(ready); completed += len(ready); upcoming = []
        for name in ready:
            for child in children[name]:
                degree[child] -= 1
                if degree[child] == 0:
                    upcoming.append(child)
        ready = sorted(upcoming)
    if completed != len(nodes):
        raise ValueError('cycle')
    return layers

