import csv, io
from decimal import Decimal, InvalidOperation, ROUND_HALF_EVEN

def _read(text):
    reader = csv.DictReader(io.StringIO(text))
    if reader.fieldnames is None or not {'id','amount'} <= set(reader.fieldnames):
        raise ValueError('headers')
    result = {}
    for row in reader:
        key = (row.get('id') or '').strip()
        if not key or key in result:
            raise ValueError('id')
        try:
            amount = Decimal((row.get('amount') or '').strip())
            if not amount.is_finite():
                raise ValueError('nonfinite')
            result[key] = amount.quantize(Decimal('.01'), rounding=ROUND_HALF_EVEN)
        except InvalidOperation as exc:
            raise ValueError('amount') from exc
    return result

def reconcile(expected_csv, paid_csv):
    expected, paid = _read(expected_csv), _read(paid_csv)
    result = []
    for key in sorted(expected.keys() | paid.keys()):
        difference = paid.get(key,Decimal(0)) - expected.get(key,Decimal(0))
        if not difference: difference = Decimal('0.00')
        status = 'missing' if key not in paid else 'unexpected' if key not in expected else 'short' if difference < 0 else 'excess' if difference > 0 else 'match'
        result.append({'id':key,'difference':format(difference,'.2f'),'status':status})
    return result

