import json

def records(chunks):
    buffer = b''
    for chunk in chunks:
        buffer += chunk
        while b'\n' in buffer:
            line, buffer = buffer.split(b'\n',1)
            if line.strip():
                yield json.loads(line.decode('utf-8'))
    if buffer.strip():
        yield json.loads(buffer.decode('utf-8'))
